/* ---------------- ตัวช่วย ---------------- */
const nm=k=>(NP[k]&&NP[k].n)||(WHO[k]&&WHO[k].n)||'เพื่อน';
const hearts=k=>Math.min(5,Math.floor(((LF().aff[k])||0)/50));
const hstr=k=>{const h=hearts(k);return '💗'.repeat(h)+'🤍'.repeat(5-h)};
const isBd=(k,c)=>{const b=NP[k]&&NP[k].bd;return !!b&&b[0]===c.mi&&b[1]===c.wd};
function aff(k,n){const L=LF();const h0=hearts(k);L.aff[k]=clamp((L.aff[k]||0)+n,0,300);const h1=hearts(k);if(h1>h0)setTimeout(()=>banner(nm(k)+' '+hstr(k),2600),200);fsave()}
function know(k,it,v){const L=LF();(L.known[k]=L.known[k]||{})[it]=v;fsave()}
const coins=(n,why)=>api().coins(n,why);
const choose=(t,o,n)=>api().choose(t,o,n);
const openOv=(h,f)=>api().openOv(h,f);
async function reward(r){if(!r)return;if(r.coins)coins(r.coins,'ของขวัญจากเพื่อน');if(r.inv)Object.keys(r.inv).forEach(k=>invAdd(k,r.inv[k]));if(r.perk){LF().perk[r.perk]=1;fsave()}if(r.snap)api().snap(r.snap)}

/* ---------------- การเดินถึง (flood fill) ---------------- */
function gridOf(key){
  if(key==='world')return SOLID?{g:SOLID,w:MW,h:MH}:null;
  if(key==='village')return VSOLID?{g:VSOLID,w:VW,h:VH}:null;
  if(key==='512')return S&&S.map==='room'&&!S.rm&&RSOLID?{g:RSOLID,w:RW,h:RH}:null;
  if(key.indexOf('rm:')===0){const b=built(key.slice(3));return b?{g:b.sol,w:RW,h:RH}:null}return null}
function blk(G,px,py){const s=(x,y)=>{const tx=Math.floor(x/T),ty=Math.floor(y/T);if(tx<0||ty<0||tx>=G.w||ty>=G.h)return 1;return G.g[ty*G.w+tx]};return s(px-5,py-4)||s(px+5,py-4)||s(px-5,py)||s(px+5,py)}
const RC={};
function reach(key){const G=gridOf(key);if(!G)return null;const c=RC[key];if(c&&c.g===G.g)return c;
  const st=key==='world'?[15,19]:key==='village'?[22,37]:[7,8];const W0=G.w,H0=G.h,R=new Uint8Array(W0*H0),ok=(x,y)=>x>=0&&y>=0&&x<W0&&y<H0&&!blk(G,x*T+8,y*T+12);
  const q=[st];if(ok(st[0],st[1]))R[st[1]*W0+st[0]]=1;else q.length=0;
  for(let i=0;i<q.length;i++){const [x,y]=q[i];[[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy])=>{const nx=x+dx,ny=y+dy;if(!ok(nx,ny)||R[ny*W0+nx])return;if(blk(G,(x+nx)/2*T+8,(y+ny)/2*T+12))return;R[ny*W0+nx]=1;q.push([nx,ny])})}
  const list=[];for(let i=0;i<R.length;i++)if(R[i])list.push(i);
  return RC[key]={g:G.g,R,w:W0,h:H0,list}}
function reachNear(key,tx,ty,occ){const r=reach(key);if(!r)return null;tx=Math.round(tx);ty=Math.round(ty);
  for(let d=0;d<30;d++)for(let dy=-d;dy<=d;dy++)for(let dx=-d;dx<=d;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==d)continue;const x=tx+dx,y=ty+dy;if(x<0||y<0||x>=r.w||y>=r.h)continue;
    if(!r.R[y*r.w+x])continue;if(occ&&occ.has(x+','+y))continue;if(key.indexOf('rm:')===0&&y>=8&&x>=6&&x<=8)continue;return {x:x*T+8,y:y*T+12,tx:x,ty:y}}return null}
function reachRand(key,R0,occ,filt){const r=reach(key);if(!r)return null;for(let t=0;t<80;t++){const i=r.list[Math.floor(R0()*r.list.length)],x=i%r.w,y=Math.floor(i/r.w);
    if(occ&&occ.has(x+','+y))continue;if(key.indexOf('rm:')===0&&y>=8&&x>=6&&x<=8)continue;if(key==='world'&&Math.hypot(x-15,y-19)<2)continue;if(filt&&!filt(x,y))continue;return {x:x*T+8,y:y*T+12,tx:x,ty:y}}return null}

