  const set=(x,y,w,h)=>{for(let j=y;j<y+(h||1);j++)for(let i=x;i<x+(w||1);i++)if(i>=0&&j>=0&&i<RW&&j<RH)sol[j*RW+i]=1};
  const R=(cl,x,y,w,h)=>{g.fillStyle=cl;g.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))};
  const f1=D.fl[0],f2=D.fl[1];for(let y=0;y<RH;y++)for(let x=0;x<RW;x++){R((x+y)%2?f1:f2,x*T,y*T,T,T);R('rgba(0,0,0,.07)',x*T,y*T+15,T,1)}
  R(D.wl,0,0,RW*T,2*T);R(shade(D.wl,.82),0,2*T-3,RW*T,3);R(shade(D.wl,.92),0,2*T-8,RW*T,2);
  R('#2a1e16',0,0,T,RH*T);R('#2a1e16',(RW-1)*T,0,T,RH*T);R('#2a1e16',0,(RH-1)*T,RW*T,T);R(f1,7*T,(RH-1)*T,T,T);R('#5a3a20',7*T,(RH-1)*T+12,T,4);R('#c8a060',7*T+3,(RH-1)*T+2,10,3);
  set(0,0,RW,2);set(0,0,1,RH);set(RW-1,0,1,RH);set(0,RH-1,RW,1);
