function placeNow(){if(!S)return null;const cur=F_().cur;if(S.map==='world')return 'sch:w';if(S.map==='village')return 'vil:w';if(S.map==='room')return S.rm?cur+':rm:'+S.rm:'sch:512';return null}
const plOf=p=>p[0]+':'+p[1];
const keyOf=pl=>pl==='sch:w'?'world':pl==='vil:w'?'village':pl==='sch:512'?'512':pl.indexOf(':rm:')>0?'rm:'+pl.split(':rm:')[1]:null;
const ALIAS=[];
function alias(i,base,name){const a='lfc'+i;SPR[a]=SPR[base];WHO[a]={n:name};return a}
const NAMES_S=['น้องเมย์','น้องต้นกล้า','น้องปาล์ม','น้องฟ้า','พี่บีม','น้องมินท์','น้องโอ๊ต','พี่แพรว','น้องเจ','น้องข้าวหอม','พี่ภูมิ','น้องน้ำใส'],NAMES_V=['ลุงคำ','ป้าศรี','น้าแก้ว','ยายบัว','ลุงจันทร์'];
const GEN_S=['ได้ยินวงดนตรีไทยซ้อมทุกเย็นเลย เพราะมาก','ครูอินโฟถ่ายรูปเราลงเพจด้วยแหละ!','ผอ.ถือโทรโข่งทักทุกคนตอนเช้า ตลกดี','กีฬาสีปีนี้สีม่วงต้องชนะ!','เมื่อวานเห็นพี่ฟูปีนต้นไม้หลังโรงอาหาร','ห้องสมุดมีหนังสือเรื่องผีโรงเรียนด้วย น่ากลัวมาก','ตอนกลางคืนอย่าเดินแถวอาคาร 2 นะ รุ่นพี่เล่ากันมา'];
const GEN_V=['ลมจากแม่น้ำเมยเย็นสบายนะลูก','ปีนี้มะม่วงออกลูกดก เก็บไปกินได้เลย','เสียงกลองหลวงซ้อมตอนเย็น ฟังแล้วใจฟู','ริมน้ำมีหินสวย ๆ เยอะ ระวังลื่นนะ'];
function hintLine(R0){const ks=Object.keys(NP).filter(k=>NP[k].love&&NP[k].love.length);const k=ks[Math.floor(R0()*ks.length)],it=NP[k].love[Math.floor(R0()*NP[k].love.length)];return 'ได้ยินว่า'+NP[k].n+'ชอบ'+GI[it][0]+'มากเลยนะ'}
function buildEnts(pl){
  const F=F_(),c=cal(),h=hourF(),L=LF(),occ=new Set(),list=[],key=keyOf(pl),isRoom=pl.indexOf(':rm:')>0,rid=isRoom?pl.split(':rm:')[1]:null,D=rid?ROOMS[rid]:null;
  const take=p=>{if(p)occ.add(p.tx+','+p.ty);return p};
  const roomSpot=(k,own)=>{if(own)return take({x:own[0]*T+8,y:own[1]*T+12,tx:own[0],ty:own[1]});const r=reach(key);if(!r)return null;const R0=rng(hsh(k+pl+F.day));return take(reachRand(key,R0,occ,(x,y)=>y>=2))};
  if(D&&D.fixed)D.fixed.forEach((fx,i)=>{const p=take({x:fx.at[0]*T+8,y:fx.at[1]*T+12,tx:fx.at[0],ty:fx.at[1]});const sk=fx.mon?fx.k:(fx.nm?alias(20+i,fx.k,fx.nm):fx.k);list.push({id:'fx'+i,k:sk,base:fx.k,x:p.x,y:p.y,bx:p.x,by:p.y,dir:'d',fixed:1,mon:fx.mon,lines:fx.lines})});
  const q=F.rq[F.cur];
  Object.keys(NP).forEach(k=>{const N=NP[k];if(!N.sched)return;if(S.party&&S.party.includes(k))return;if(q&&(q.g.k===k||q.k2===k))return;
    const p=N.sched(c,h,k);if(!p||plOf(p)!==pl)return;let pos=null;
    if(pl==='sch:512'){const sp=S512.filter(s=>!occ.has(s[0]+','+s[1]));const s=sp[hsh(k)%Math.max(1,sp.length)];if(s)pos=take({x:s[0]*T+8,y:s[1]*T+12,tx:s[0],ty:s[1]})}
    else if(isRoom)pos=roomSpot(k,D&&D.own&&D.own[k]);
    else{const t=p[2]||[20,20];pos=take(reachNear(key,t[0],t[1],occ))}
    if(pos)list.push({id:k,k,base:k,x:pos.x,y:pos.y,bx:pos.x,by:pos.y,dir:'d',named:1})});
  // คนสุ่ม
  const R0=rng(hsh(pl+':'+F.day+':'+Math.floor(h/2)));let n=0,pool=[],lines=GEN_S,names=NAMES_S,anch=null;
  if(D){if(!openNow(D))n=0;else{const cr=D.crowd||[0,0];n=cr[0]+Math.floor(R0()*(cr[1]-cr[0]+1));if(D.school&&!school(c))n=Math.min(n,R0()<.5?1:0)}pool=D.pool||['stuA'];lines=(D.say||[]).concat(D.map==='vil'?GEN_V:GEN_S);names=D.map==='vil'?NAMES_V.concat(['น้องแป้ง','น้องตะวัน']):NAMES_S}
  else if(pl==='sch:w'){n=school(c)&&h>=7&&h<17?5:h>=7&&h<18?2:0;pool=['stuA','stuB','stuC','stuD'];anch=[[28,27],[24,20],[40,26],[33,13],[14,19],[46,12],[30,34],[20,9],[11,25]]}
  else if(pl==='vil:w'){n=h>=6&&h<19?3:0;pool=['villM','villF','kid','kidG'];lines=GEN_V;names=NAMES_V.concat(['น้องแป้ง','น้องตะวัน']);anch=[[19,29],[25,16],[30,30],[12,20],[24,34],[33,8]]}
  for(let i=0;i<n;i++){const base=pool[Math.floor(R0()*pool.length)];let pos=null;
    if(anch){const a=anch[Math.floor(R0()*anch.length)];pos=take(reachNear(key,a[0]+Math.floor(R0()*5)-2,a[1]+Math.floor(R0()*5)-2,occ))}else pos=take(reachRand(key,R0,occ,(x,y)=>y>=2));
    if(!pos)continue;const name=/^(kid|kidG)$/.test(base)?(R0()<.5?'น้องตะวัน':'น้องแป้ง'):/^vill/.test(base)?names[Math.floor(R0()*names.length)]:/^tch/.test(base)?'คุณครู':names[Math.floor(R0()*names.length)];
    const a=alias(i,base,name);const ls=[];for(let j=0;j<2;j++)ls.push(R0()<.35?hintLine(R0):lines[Math.floor(R0()*lines.length)]);
    list.push({id:'cr'+i,k:a,base,x:pos.x,y:pos.y,bx:pos.x,by:pos.y,dir:['d','l','r','u'][Math.floor(R0()*4)],lines:ls,crowd:1})}
  return list}
let EC={key:'',list:[]};
function ents(){if(!ON())return [];const pl=placeNow();if(!pl)return [];const F=F_();
  const q=F.rq[F.cur];const key=pl+'|'+F.day+'|'+Math.floor(F.clock/20)+'|'+(S.party||[]).join(',')+'|'+(q?q.g.k+q.st:'')+'|'+LF().gen;
  if(EC.key===key&&LIFE._ents!==null)return EC.list;
  const list=buildEnts(pl),old=new Map(EC.list.map(e=>[e.id+e.k,e]));list.forEach(e=>{const o=old.get(e.id+e.k);if(o&&o.bx===e.bx&&o.by===e.by){e.x=o.x;e.y=o.y;e.dir=o.dir;e.tm=o.tm}});
  EC={key,list};LIFE._ents=1;return list}

/* ---------------- ของเก็บได้ประจำวัน ---------------- */
const FG_W=[['flower',3],['coin',2],['mali',1],['leaf',1]],FG_V=[['mango',2],['stone',2],['flower',2]],FG_R=['lib','b2cls','cant','b8hall','b4com','b6art','dome','b3lab','b5dance','council'];
function fgToday(){const L=LF(),F=F_();if(!L.fg||L.fg.day!==F.day){const R0=rng(hsh('fg'+F.day)),items=[];let id=0;
    FG_W.forEach(([it,n])=>{for(let i=0;i<n;i++)items.push({id:id++,pl:'sch:w',it})});FG_V.forEach(([it,n])=>{for(let i=0;i<n;i++)items.push({id:id++,pl:'vil:w',it})});
    const rs=FG_R.slice().sort(()=>R0()-.5).slice(0,2);rs.forEach(r=>items.push({id:id++,pl:(ROOMS[r].map==='vil'?'vil':'sch')+':rm:'+r,it:R0()<.7?'coin':'snack'}));
    L.fg={day:F.day,items};fsave()}return L.fg}
function fgHere(){const pl=placeNow();if(!pl)return [];const fg=fgToday(),key=keyOf(pl);if(!key||key==='512')return [];const out=[];
  fg.items.forEach(it=>{if(it.got||it.pl!==pl)return;if(it.x==null){const R0=rng(hsh('fgp'+fg.day+':'+it.id));const occ=new Set(fg.items.filter(o=>o.tx!=null).map(o=>o.tx+','+o.ty));
      const filt=it.it==='stone'?((x,y)=>x>=rxv(y)&&x<=sxv(y)):((x,y)=>y>=2);const p=reachRand(key,R0,occ,filt)||reachRand(key,R0,occ);if(!p)return;it.x=p.x;it.y=p.y;it.tx=p.tx;it.ty=p.ty;fsave()}out.push(it)});return out}
function drawFg(g,it,x,y,t){const R=(c,a,b,w,h)=>{g.fillStyle=c;g.fillRect(Math.round(x+a),Math.round(y+b),w,h)};const k=(Math.sin(t*4+it.id)+1)/2;
  g.fillStyle='rgba(255,240,160,'+(.18+.18*k)+')';g.beginPath();g.ellipse(x,y,7,3,0,0,7);g.fill();
  if(it.it==='flower'){R('#3a8a3a',-1,-6,1,6);[[0,-9],[-2,-7],[2,-7],[0,-5]].forEach(([a,b])=>R('#ffd34d',a-1,b-1,2,2));R('#e86a2a',-1,-8,2,2)}
  else if(it.it==='mali'){R('#3a8a3a',-1,-5,1,5);R('#ffffff',-3,-9,6,3);R('#ffffff',-2,-10,4,5)}
  else if(it.it==='leaf'){R('#4a9a44',-3,-7,5,4);R('#2a6a2a',1,-11,1,6);R('#2a6a2a',1,-11,3,1)}
  else if(it.it==='mango'){R('#f2b030',-3,-7,6,5);R('#e8901a',-2,-3,4,1);R('#3a8a3a',0,-8,2,1)}
  else if(it.it==='stone'){R('#8a7ab0',-3,-5,6,4);R('#c8a8e8',-2,-5,2,1)}
  else if(it.it==='snack'){R('#e8c070',-3,-6,6,4);R('#c08030',-3,-3,6,1)}
  else{R('#c8901a',-2,-7,5,5);R('#ffd34d',-2,-8,4,4);R('#fff6c0',-1,-7,1,1)}}

/* ---------------- งานประจำปี: ตำแหน่งและการทำงาน ---------------- */
const festDone=(f,c)=>!!LF().fest[f.id+':'+(f.once?1:c.y)];
function festToday(c){c=c||cal();const L=LF();return FEST.filter(f=>f.mi===c.mi&&f.wd===c.wd&&!f.info&&!(f.once&&(c.y>1||L.gen>=2)))}
function festMarks(){const pl=placeNow();if(!pl)return [];const c=cal(),h=hourF();return festToday(c).filter(f=>!festDone(f,c)&&plOf(f.at)===pl&&h>=f.h[0]&&h<f.h[1]).map(f=>{const key=keyOf(pl);const t=f.at[2];
  const p=pl==='sch:512'?{x:t[0]*T+8,y:t[1]*T+12}:(reachNear(key,t[0],t[1])||{x:t[0]*T+8,y:t[1]*T+12});return {f,x:p.x,y:p.y}})}
function newsMark(){const L=LF(),F=F_();const n=L.news;if(!n||n.day!==F.day||n.done)return null;const N=NEWS[n.i],pl=placeNow();if(!N||plOf(N.at)!==pl)return null;const h=hourF();if(N.h&&(h<N.h[0]||h>=N.h[1]))return null;
  const key=keyOf(pl),t=N.at[2];const p=pl==='sch:512'?{x:t[0]*T+8,y:t[1]*T+12}:(reachNear(key,t[0],t[1])||{x:t[0]*T+8,y:t[1]*T+12});return {N,x:p.x,y:p.y}}
async function bandSong(title,s,b0,nb,bg){const phr=SB.phrases(s).filter(p=>p.b0>=b0&&p.b0<b0+nb);if(!phr.length)return 1;let ph=0,ok=0,tot=0;const nph=phr.length;
  const e=Object.assign({},ENEMY.note,{k:'mini',n:title,hp:100,atk:3,phr:[4,4],gap:.52,show:4,slot:.32,echoOnly:1});if(bg)e.bg=bg;['item','item3','boss','final','haze','call','ghost','pats'].forEach(k=>delete e[k]);
  e.seqFn=seq=>{const q=phr[Math.min(ph,nph-1)];seq.length=0;q.n.forEach(g=>seq.push(g));ph++;e.show=ph<=2?q.n.length:ph<=4?2:1;if(BT)bmsg('ห้องเพลงที่ '+(q.b0+1)+' · วรรคที่ '+ph+'/'+nph)};
  e.onEcho=res=>{res.forEach(v=>{tot++;if(v===1)ok++});if(BT){BT.hp=Math.max(0,Math.round(BT.max*(1-Math.min(1,ph/nph))));ebar();if(ph>=nph)BT.songDone=1}};
  ENEMY.lfSong=e;const r=await battle('lfSong');return r==='win'?(tot?ok/tot:1):-1}
const song=k=>SB.builtin.find(b=>b.key===k)||SB.builtin[0];
const partyAff=n=>(S.party||[]).forEach(k=>{if(NP[k])aff(k,n)});
async function quiz(qs,title){let ok=0;for(let i=0;i<qs.length;i++){const q=qs[i],ord=[0,1,2].sort(()=>Math.random()-.5);const v=await choose(title+' ข้อ '+(i+1)+'/'+qs.length,ord.map(j=>({t:q[1][j]})),esc(q[0]));
  if(ord[v]===0){ok++;await say(null,'ถูกต้อง! '+(q[2]||''))}else await say(null,'ยังไม่ใช่ · คำตอบคือ “'+q[1][0]+'” '+(q[2]||''))}return ok}
