/* ---------------- คุยกับตัวละคร ---------------- */
function tier(k){const h=hearts(k);return h>=4?2:h>=2?1:0}
async function npcHook(k){const L=LF(),F=F_(),N=NP[k];if(!N)return false;L.met[k]=1;
  if(N.h5&&hearts(k)>=5&&!(L.hev[k]&&L.hev[k][5])){(L.hev[k]=L.hev[k]||{})[5]=1;fsave();await talk(N.h5);await reward(N.r5);api().snap('เพื่อนสนิท · '+N.n);return true}
  if(N.h3&&hearts(k)>=3&&!(L.hev[k]&&L.hev[k][3])){(L.hev[k]=L.hev[k]||{})[3]=1;fsave();await talk(N.h3);aff(k,4);return true}
  if(L.talk[k]!==F.day){L.talk[k]=F.day;aff(k,4)}return false}
function ctxLines(k,c){const L=LF(),out=[];
  if(isBd(k,c))out.push('วันนี้วันเกิดเรานะ! ใครให้ของขวัญวันนี้ เราดีใจเป็นสามเท่าเลย');
  if(k==='dir'&&L.gen<2&&c.y===1&&c.mi>=10)out.push(c.mi===11?'สิ้นเดือนนี้ ผอ.ก็เกษียณแล้ว… ผอ.จะคิดถึงเสียงฆ้องตอนเย็นนะลูก':'อีกไม่กี่เดือน ผอ.ก็จะเกษียณแล้วนะ อายุหกสิบพอดี เร็วจังเลย');
  if(k==='dir'&&L.gen>=2&&NP.dir.tr)out.push(NP.dir.tr[Math.floor(Math.random()*NP.dir.tr.length)]);
  if(k==='dir2'&&!L.met2){L.met2=1;out.unshift('สวัสดีจ้ะ ผอ.ศิริพร ผอ.คนใหม่ของสรรพวิทยาคม ผอ.เราะห์มานเล่าเรื่องชมรมเธอให้ฟังเยอะเลย ฝากตัวด้วยนะ')}
  if(k==='info'&&c.y===1&&c.mi===11&&L.gen<2&&!L.wishOn){L.wishOn=1;fsave();out.push('ครูกำลังทำคลิปงานเกษียณ ผอ.! ช่วยเก็บคำอวยพรจากคนในโรงเรียนให้หน่อย อย่างน้อยห้าคนนะจ๊ะ ใครมีปุ่ม 💌 ก็ขอได้เลย')}
  return out}
async function npcTalk(k,ent){const N=NP[k];if(!N)return;if(ent)faceTo(ent);const c=cal();
  if(await npcHook(k)){await npcMenu(k);return}
  const ls=ctxLines(k,c);const pool=(k==='dir'&&LF().gen>=2)?[]:(N.t?N.t[tier(k)]:[]);if(!ls.length&&pool.length)ls.push(pool[Math.floor(Math.random()*pool.length)]);if(!ls.length)ls.push('สวัสดีจ้ะ');
  await talk(ls.map(t=>[k,t]));await npcMenu(k)}
async function npcMenu(k){const L=LF(),F=F_();const opts=[];
  if(L.gift[k]!==F.day)opts.push({t:'🎁 ให้ของขวัญ',f:()=>giftTo(k)});
  specials(k).forEach(o=>opts.push(o));if(!opts.length)return;opts.push({t:'แค่แวะมาทัก '+hstr(k)});
  const v=await choose(nm(k)+' '+hstr(k),opts.map(o=>({t:o.t})));const o=opts[v];if(o&&o.f)await o.f()}
function specials(k){const L=LF(),F=F_(),c=cal(),o=[];
  if(k==='info'){o.push({t:L.news&&L.news.day===F.day?(L.news.done?'📰 งานข่าววันนี้เสร็จแล้ว':'📰 งานข่าววันนี้: '+NEWS[L.news.i].cap):'📰 รับงานข่าวลงเพจ',f:newsTask});if(L.day.gos!==F.day)o.push({t:'🗣️ ฟังซุบซิบ',f:gossip})}
  if(k==='dir'&&L.day.joke!==F.day)o.push({t:'😂 ฟังมุก ผอ.',f:dirJoke});
  if(k==='dir'&&L.gen<2&&placeNow()==='sch:w'&&hourF()>=13&&hourF()<15&&L.day.water!==F.day)o.push({t:'🌱 ช่วย ผอ.รดน้ำต้นไม้',f:water});
  if(L.wishOn&&L.gen<2&&!L.wish[k]&&NP[k].wish&&k!=='dir')o.push({t:'💌 ขอคำอวยพรให้ ผอ.',f:()=>askWish(k)});
  return o}
async function giftTo(k){const L=LF(),F=F_(),N=NP[k];if(L.gift[k]===F.day){await say(k,'วันนี้ให้ของแล้วนะ ไว้พรุ่งนี้ค่อยให้ใหม่');return}
  const ks=Object.keys(GI).filter(i=>i!=='yadom'&&invN(i)>0);if(!ks.length){await say(null,'ยังไม่มีของขวัญในกระเป๋า · ซื้อที่ร้านค้า หรือเก็บดอกไม้ มะม่วง หินสวยตามทาง');return}
  const v=await choose('ให้ของขวัญ '+nm(k),ks.map(i=>({t:GI[i][1]+' '+GI[i][0]+' ×'+invN(i),s:(LF().known[k]||{})[i]?{love:'💗 ชอบมาก',like:'🙂 ชอบ',ok:'😐 เฉย ๆ',hate:'😣 ไม่ชอบ'}[LF().known[k][i]]:''})).concat([{t:'ยกเลิก'}]));if(isNaN(v)||v>=ks.length)return;const it=ks[v];
  if((k==='dir')&&it==='moo'){await talk([['dir','ขอบใจนะลูก แต่ ผอ.เป็นมุสลิม ไม่ทานหมูนะ'],['dir','ไม่เป็นไรเลย ผอ.ดีใจที่ลูกนึกถึง เก็บไว้ให้จักรเถอะ เขาชอบ ฮ่า ๆ']]);banner('รู้ไว้: เพื่อนมุสลิมไม่รับประทานหมู · ลองให้โรตี ชาชัก หรืออินทผลัมแทน',4000);know(k,'moo','hate');return}
  invUse(it);L.gift[k]=F.day;const c=cal();const pref=N.love.includes(it)?3:N.like.includes(it)?2:N.hate.includes(it)?0:1;let pts=[-6,3,8,14][pref];
  const bd=isBd(k,c);if(bd&&pts>0)pts*=3;if(pts>0&&N.teacher&&c.mi===3&&c.wd===2)pts*=2;if(pts>0&&it==='mali'&&c.mi===10&&c.wd===4)pts*=3;
  know(k,it,['hate','ok','like','love'][pref]);
  const line=pref===3?(N.lv||'ชอบมาก! ขอบใจนะ'):pref===2?LIKEL[Math.floor(Math.random()*LIKEL.length)]:pref===0?(N.hv||HATEL[Math.floor(Math.random()*HATEL.length)]):OKL[Math.floor(Math.random()*OKL.length)];
  await say(k,(bd&&pts>0?'วันเกิดเราด้วย! ':'')+line);aff(k,pts);try{if(pref>=2)sfx.get()}catch(e){}fsave()}
async function newsTask(){const L=LF(),F=F_();if(L.news&&L.news.day===F.day){await say('info',L.news.done?'ส่งภาพแล้ว ยอดไลก์พุ่งเลยจ้ะ ขอบใจนะ':'ยังไม่ได้ภาพ “'+NEWS[L.news.i].cap+'” เลยนะจ๊ะ ไปที่นั่นแล้วมองหาไอคอนกล้อง 📷'+(NEWS[L.news.i].h?' (ช่วง '+NEWS[L.news.i].h[0]+':00–'+NEWS[L.news.i].h[1]+':00)':''));return}
  const i=hsh('news'+F.day)%NEWS.length;L.news={day:F.day,i,done:0};fsave();const N=NEWS[i];
  await talk([['info','งานด่วน! ครูอยากได้ภาพ “'+N.cap+'” ลงเพจวันนี้'],['info','ไปที่นั่น'+(N.h?' ช่วง '+N.h[0]+':00–'+N.h[1]+':00 น.':'')+' แล้วกดถ่ายตรงไอคอนกล้อง 📷 นะจ๊ะ ได้ภาพแล้วครูให้ค่าเหนื่อยเลย']])}
async function shootNews(m){const L=LF();L.news.done=1;fsave();try{flash('#ffffff',200);sfx.get()}catch(e){}await sleep(300);api().snap('ข่าวเพจ · '+m.N.cap);coins(12,'งานข่าวครูอินโฟ');aff('info',6);await say(null,'แชะ! ได้ภาพ “'+m.N.cap+'” ส่งให้ครูอินโฟลงเพจแล้ว')}
async function gossip(){const L=LF(),F=F_();L.day.gos=F.day;fsave();const c=cal();
  const up=Object.keys(NP).filter(k=>k!=='info'&&NP[k].bd).map(k=>{const b=NP[k].bd;let d=dayOf(c.y,b[0],b[1])-F.day;if(d<0)d+=YD;return [k,d]}).filter(x=>x[1]>0&&x[1]<=7).sort((a,b)=>a[1]-b[1]);
  if(up.length&&Math.random()<.45){const [k,d]=up[0];await say('info','ข่าวลับ! อีก '+d+' วันเป็นวันเกิดของ'+NP[k].n+' (วัน'+WD[NP[k].bd[1]]+' '+MN[NP[k].bd[0]]+') เตรียมของขวัญให้ดีนะจ๊ะ');aff('info',2);return}
  const cand=[];Object.keys(NP).forEach(k=>{if(k==='info')return;(NP[k].love||[]).forEach(it=>{if(!(L.known[k]||{})[it])cand.push([k,it])})});
  if(cand.length&&Math.random()<.8){const [k,it]=cand[Math.floor(Math.random()*cand.length)];know(k,it,'love');await say('info','ได้ข่าวมาว่า'+NP[k].n+'ชอบ'+GI[it][1]+' '+GI[it][0]+'มากเลยนะจ๊ะ (อย่าบอกว่าครูเล่านะ ฮิ ๆ)');aff('info',2);return}
  await say('info',['ได้ข่าวว่าพบธรรมแอบซ้อมปี่แนตอนตีห้า ข้างบ้านโทรมาฟ้องครูเลย','ผอ.ลืมรองเท้าไว้ในห้องประชุมอีกแล้ว เดินเท้าเปล่าทั้งบ่าย','ครูโอโทรหาครูตังค์วันละสามรอบ ชวนกินหมูกระทะ','ป้าแดงแอบเต้นตามเสียงวงตอนล้างจานทุกเย็นนะ'][Math.floor(Math.random()*4)]);aff('info',2)}
async function dirJoke(){const L=LF();L.day.joke=F_().day;fsave();await talk([['dir',JOKES[Math.floor(Math.random()*JOKES.length)]],['dir','ฮ่า ๆ ๆ ๆ… ขำไหมลูก ขำสิ ผอ.ขอร้อง']]);aff('dir',2)}
async function water(){const L=LF();L.day.water=F_().day;fsave();await talk([[null,'ช่วย ผอ.รดน้ำแปลงดอกไม้หน้าอาคาร 6'],['dir','รดเบา ๆ เป็นจังหวะ… ซ่า… ซ่า… เหมือนเพลงสองชั้นเลยลูก'],['dir','ขอบใจนะ ต้นไม้ชอบคนใจดี ผอ.ก็ชอบ ฮ่า ๆ']]);coins(6,'ช่วย ผอ.รดน้ำต้นไม้');aff('dir',5)}
async function askWish(k){const L=LF();L.wish[k]=1;fsave();await say(k,NP[k].wish);const n=Object.keys(L.wish).length;banner('💌 คำอวยพรให้ ผอ. '+n+' คน'+(n>=5?' · ครบแล้ว! ยิ่งเยอะยิ่งดี':''),2600)}
function faceTo(e){const dx=S.x-e.x,dy=S.y-e.y;e.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'r':'l'):(dy>0?'d':'u')}
async function crowdTalk(e){faceTo(e);await talk((e.lines||['สวัสดีจ้ะ']).slice(0,1+(Math.random()<.5?1:0)).map(t=>[e.k,t]))}

/* ---------------- สิ่งของในห้อง ---------------- */
async function roomAct(a){const L=LF(),F=F_();
  if(a==='dirDesk'){await say(null,'บนโต๊ะ ผอ. มีกองเอกสาร โรตีครึ่งชิ้น และแว่นตาสามอัน (ผอ.หาแว่นไม่เจอเลยซื้อใหม่ทุกครั้ง)');return}
  if(a==='trophy'){await say(null,'ตู้ถ้วยรางวัลของโรงเรียน มีถ้วยวงดนตรีไทยหลายใบ ป้ายทองเขียนว่า “ก่อตั้ง 30 พฤศจิกายน 2458”');api().lore('L1');return}
  if(a==='dirShelf'){await say(null,'ชั้นหนังสือ ผอ.: “ปลูกผักสวนครัวง่าย ๆ” · “มุกตลกสำหรับผู้บริหาร เล่ม 3” · “บริหารโรงเรียนด้วยหัวใจ”');return}
  if(a==='prDesk'||a==='prBoard'){await calendarScreen();return}
  if(a==='prCam'){await say(null,'กล้องตัวใหญ่ของครูอินโฟ เลนส์ยาวเท่าแขน… มีกระดาษแปะว่า “ห้ามจับ! (ยกเว้นคนสวย)”');return}
  if(a==='board'){await say(null,'บนกระดาน: '+FACTS[hsh(F.day+(S.rm||''))%FACTS.length]);return}
  if(a==='lab'){const q=SCIQ[hsh('lab'+F.day)%SCIQ.length];await say(null,'แผ่นทดลองบนโต๊ะ: “'+q[0]+'” · คำตอบ: '+q[1][0]+' — '+q[2]);return}
  if(a==='pc'){await say(null,'เปิดเพจโรงเรียน… มีภาพที่ระลึกของวงเราด้วย!');await api().album();return}
  if(a==='mirror'){await say(null,'ฝึกท่ารำหน้ากระจก… วงแขนแบบนี้… พบธรรมจีบมือเหมือนกำลังจับปู');S.hp=Math.min(S.hpMax,S.hp+S.hpMax*.2);hud();return}
  if(a==='easel'){if(L.day.paint!==F.day){L.day.paint=F.day;fsave();await say(null,'วาดภาพฆ้องวงใหญ่ลงผ้าใบ… ครูตังค์เดินมาดูแล้วพยักหน้า “ใช้ได้ ๆ”');coins(5,'งานศิลปะ')}else await say(null,'วันนี้วาดไปแล้ว ภาพยังไม่แห้งเลย');return}
  if(a==='tools'){await say(null,'โต๊ะช่างมีไม้อัดเหลือจากทำป้ายกีฬาสี กับกระดาษทรายสำหรับขัดรางระนาด');return}
  if(a==='ping'){await say(null,['ป๊อก… ป๊อก… ป๊อก… ตีปิงปองโต้ได้สิบครั้ง! เหงื่อออกนิดหน่อย','ตีแรงไป ลูกปิงปองเด้งไปโดนหัวพบธรรม','ตีโต้กันเป็นจังหวะเหมือนฉิ่งฉับ สนุกดี'][Math.floor(Math.random()*3)]);S.hp=Math.min(S.hpMax,S.hp+S.hpMax*.3);hud();return}
  if(a==='bed'){await say(null,'นอนพักบนเตียงพยาบาลแป๊บนึง… หายเหนื่อยแล้ว');S.hp=S.hpMax;hud();try{sfx.heal()}catch(e){}save();return}
  if(a==='shopCant')return shop('โรงอาหาร · ร้านข้าวแกงป้าแดง','cant');if(a==='shopHalal')return shop('ร้านโรตีบังเล็ก (ฮาลาล)','halal');if(a==='shopSeven')return shop('เซเว่นหน้าโรงเรียน','seven');if(a==='shopRim')return shop('ร้านข้าวริมเมย','rim');
  if(a==='khun'){await khunTalk();return}
  if(a==='books'){const ks=['L2','L3','L4','L5','L6'].filter(k=>!F.lore[k]);if(ks.length&&L.day.book!==F.day){L.day.book=F.day;fsave();await say(null,'หยิบหนังสือประวัติท้องถิ่นมาอ่าน… เจอเรื่องที่น่าสนใจ!');api().lore(ks[0])}else await say(null,'หนังสือประวัติแม่สอดเล่มหนา มีรูปแม่น้ำเมยกับดอยดินจี่ (วันนี้อ่านไปแล้ว)');return}
  if(a==='books2'){await say(null,'หนังสือดนตรีไทยเปิดค้างไว้: '+FACTS[Math.floor(Math.random()*FACTS.length)]);return}
  if(a==='domeStage'){await say(null,'ยืนบนเวทีโดม ตะโกนเบา ๆ “สรรพวาทิต!” เสียงก้องกลับมาสามรอบ… ใจฮึกเหิม');S.hp=Math.min(S.hpMax,S.hp+S.hpMax*.5);hud();return}
  if(a==='voc'){await say(null,'เครื่องเลื่อยจักรตอนนี้เลื่อยไม้ตามจังหวะช้า ๆ อย่างสงบ ไม่รัวมั่วแล้ว');return}
  if(a==='council'){await say(null,'ตู้เอกสารสภา มีแฟ้มรายงานของกัปตัน 128 ฉบับ เรียงตามวันที่อย่างเป๊ะ');return}
  if(a==='meet'){await say(null,'วาระการประชุม: “ข้อ 1 ขอห้อง 512 เปิด 24 ชั่วโมง (เสนอโดยพบธรรม) — ตกไป · ข้อ 2 เพิ่มชาเย็นในโรงอาหาร — ผ่าน!”');return}
  if(a==='cook'){if(L.day.cook!==F.day){L.day.cook=F.day;fsave();await talk([['tchF','มาช่วยครูทอดข้าวแต๋นไหมจ๊ะ ข้าวตากแห้งแล้ว'],[null,'ข้าวแต๋นพองฟูในกระทะ ราดน้ำแตงโมเคี่ยวหวาน ๆ']]);invAdd('khaotaen');banner('+1 🍘 ข้าวแต๋น',2000)}else await say(null,'วันนี้ทอดข้าวแต๋นไปแล้ว กลิ่นยังหอมอยู่เลย');return}
  if(a==='pray'){await say(null,'กราบพระสามครั้ง ขอให้วงเราเล่นดนตรีด้วยใจเดียวกัน… ใจสงบลงมาก');S.hp=S.hpMax;hud();save();return}
  if(a==='vboard'){await say(null,'กระดานโรงเรียนในชุมชน: “กลองหลวงคือมรดกของเรา · ซ้อมทุกวันศุกร์ที่โรงกลอง”');return}}
async function shop(name,kind){if(!kind)kind=/สหกรณ์/.test(name)?'coop':/เซเว่น/.test(name)?'seven':/ริมเมย/.test(name)?'rim':'coop';const ks=SHOPS[kind]||SHOPS.coop;const disc=LF().perk.discount?.8:1;
  while(true){const F=F_();const pr=k=>Math.max(1,Math.ceil(GI[k][2]*disc));
    const v=await choose(name+' · 🪙 '+F.coins+(disc<1?' · บัตร VIP พบธรรม ลด 20%':''),ks.map(k=>({t:GI[k][1]+' '+GI[k][0]+' · 🪙 '+pr(k),s:(isBag(k)&&ITEMS[k]?ITEMS[k].d+' · ':'ของขวัญ · ')+'มีอยู่ '+invN(k),off:F.coins<pr(k)})).concat([{t:'เสร็จแล้ว'}]));
    if(isNaN(v)||v>=ks.length)return;const k=ks[v];F.coins-=pr(k);invAdd(k);fsave();hud();try{sfx.get()}catch(e){}}}

/* ---------------- หน้าจอ: ปฏิทิน สมุดเพื่อน กระเป๋า ---------------- */
async function calendarScreen(){const c=cal(),L=LF(),F=F_();let h='<h2>📅 '+MN[c.mi]+' · ปีที่ '+c.y+' <small style="font-size:13px;opacity:.8">'+termText(c)+'</small></h2>';
  const bd=Object.keys(NP).filter(k=>NP[k].bd&&(L.met[k]||L.perk.bdays));
  for(let m=0;m<3;m++){const mi=(c.mi+m)%12,yy=c.y+Math.floor((c.mi+m)/12);h+='<div style="margin:6px 0 2px;color:#f2c14e;font-size:14px">'+MN[mi]+(m?'':' (เดือนนี้)')+'</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px">';
    for(let wd=0;wd<7;wd++){const d=dayOf(yy,mi,wd),today=d===F.day,fs=FEST.filter(f=>f.mi===mi&&f.wd===wd&&!(f.once&&(yy>1||L.gen>=2))),bs=bd.filter(k=>NP[k].bd[0]===mi&&NP[k].bd[1]===wd),tm=TERM(mi)&&wd<5;
      h+='<div style="border:2px solid '+(today?'#ffd34d':'#4a3570')+';border-radius:6px;background:'+(tm?'#22163a':'#2e2048')+';padding:3px;font-size:11px;min-height:46px;line-height:1.25"><b>'+WDS[wd]+' '+Math.round(1+wd*(ML[mi]-1)/6)+'</b><br>'+fs.map(f=>'<span title="'+esc(f.nm)+'">🎉</span>').join('')+bs.map(k=>'<span title="วันเกิด'+esc(NP[k].n)+'">🎂</span>').join('')+'</div>'}h+='</div>'}
  const up=[];for(let m=0;m<3;m++){const mi=(c.mi+m)%12;FEST.filter(f=>f.mi===mi&&!(f.once&&(c.y>1||L.gen>=2))).forEach(f=>up.push('🎉 '+MS[mi]+' วัน'+WD[f.wd]+' · '+f.nm));bd.filter(k=>NP[k].bd[0]===mi).forEach(k=>up.push('🎂 '+MS[mi]+' วัน'+WD[NP[k].bd[1]]+' · วันเกิด'+NP[k].n))}
  h+='<ul class="chk">'+up.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><p style="font-size:12px;opacity:.75">1 เดือนในเกม = 7 วัน · จ.–ศ. ช่วงเปิดเทอมมีเรียน · วันเกิดจะขึ้นเมื่อรู้จักกันแล้ว</p><button class="btn s" data-a="x">ปิด</button>';await openOv(h)}
async function friendBook(){const L=LF();const all=Object.keys(NP).filter(k=>!(k==='dir2'&&L.gen<2)),ks=all.filter(k=>L.met[k]).sort((a,b)=>(L.aff[b]||0)-(L.aff[a]||0)),unk=all.length-ks.length;let h='<h2>💗 สมุดเพื่อน · รู้จักแล้ว '+ks.length+'/'+all.length+'</h2><div class="lst">';
  ks.forEach(k=>{const N=NP[k];
    const kn=L.known[k]||{},loves=(L.perk.gossip?N.love:N.love.filter(i=>kn[i])).map(i=>GI[i][1]).join(' '),hates=N.hate.filter(i=>kn[i]).map(i=>GI[i][1]).join(' ');
    h+='<div class="lore"><b>'+esc(N.n)+'</b> '+hstr(k)+(L.talk[k]===F_().day?' 💬':'')+(L.gift[k]===F_().day?' 🎁':'')+'<br><small>วันเกิด: วัน'+WD[N.bd[1]]+' '+MN[N.bd[0]]+(loves?' · ชอบมาก: '+loves:'')+(hates?' · ไม่ชอบ: '+hates:'')+'</small></div>'});
  h+=(unk?'<div class="lore no">ยังไม่รู้จักอีก '+unk+' คน · ลองเดินไปตามห้องเรียน โรงอาหาร ห้อง 512 และแม่โกนเกน</div>':'')+'</div><p style="font-size:12px;opacity:.75">คุยทุกวันได้ใจ · ให้ของที่ชอบได้ใจมาก · วันเกิดได้สามเท่า · หัวใจ 3 และ 5 ดวงมีฉากพิเศษ</p><button class="btn s" data-a="x">ปิด</button>';await openOv(h)}
async function bagScreen(){const ks=Object.keys(GI).filter(k=>invN(k)>0);await openOv('<h2>🎒 กระเป๋าของขวัญ</h2>'+(ks.length?'<div class="lst">'+ks.map(k=>'<div class="lore">'+GI[k][1]+' <b>'+esc(GI[k][0])+'</b> ×'+invN(k)+'</div>').join('')+'</div>':'<p>ยังว่างอยู่ · ซื้อที่ร้านค้า หรือเก็บดอกไม้ มะม่วง หินสวยตามทาง</p>')+'<p style="font-size:12px;opacity:.75">ให้ของขวัญได้คนละหนึ่งชิ้นต่อวัน · ดูว่าใครชอบอะไรได้ที่สมุดเพื่อน (ครูอินโฟชอบเล่า)</p><button class="btn s" data-a="x">ปิด</button>')}
